"""mpl_toolkits.axisartist.axis_artist — axis artist."""

from matplotlib.artist import Artist

class AxisArtist(Artist):
    """One axis spine + its ticks + tick-labels + axis-label, as a
    single composite artist. The plotly backend handles axis rendering
    itself, but we still track every component's state so callers that
    poll ``axis.major_ticklabels.get_text()`` etc. see the right values.
    """

    def __init__(self, axes, helper, offset=None, axis_direction='bottom'):
        super().__init__()
        self.axes = axes
        self.helper = helper
        self.offset = offset
        self.axis_direction = axis_direction
        self.major_ticklabels = TickLabels()
        self.minor_ticklabels = TickLabels()
        self.label = AxisLabel()
        self.major_ticks = Ticks(10)
        self.minor_ticks = Ticks(5)
        self.line = AxisLine()
        self._visible = True

    def set_visible(self, b):
        self._visible = bool(b)
        # Propagate so toggling the artist hides every component.
        for component in (self.major_ticklabels, self.minor_ticklabels,
                           self.label, self.major_ticks, self.minor_ticks,
                           self.line):
            component.set_visible(b)

    def get_visible(self):
        return self._visible

    def toggle(self, all=None, ticks=None, ticklabels=None, label=None):
        """Show/hide individual components. ``all`` is a shortcut to set
        the same value on all four. ``None`` leaves a component alone."""
        if all is not None:
            ticks = ticklabels = label = all
        if ticks is not None:
            self.major_ticks.set_visible(bool(ticks))
            self.minor_ticks.set_visible(bool(ticks))
        if ticklabels is not None:
            self.major_ticklabels.set_visible(bool(ticklabels))
            self.minor_ticklabels.set_visible(bool(ticklabels))
        if label is not None:
            self.label.set_visible(bool(label))


class AxisLabel:
    """Text label drawn alongside the axis line."""

    def __init__(self, text=''):
        self._text = text
        self._visible = True
        self._fontsize = 12.0
        self._color = 'black'

    def set_text(self, s):
        self._text = '' if s is None else str(s)

    def get_text(self):
        return self._text

    def set_visible(self, b):
        self._visible = bool(b)

    def get_visible(self):
        return self._visible

    def set_color(self, c):  self._color = c
    def get_color(self):     return self._color

    def set_fontsize(self, s): self._fontsize = float(s)
    def get_fontsize(self):    return self._fontsize


class TickLabels:
    """Per-axis tick-label container — holds the text strings and a
    visibility flag."""

    def __init__(self):
        self._labels = []
        self._visible = True
        self._fontsize = 10.0
        self._color = 'black'
        self._rotation = 0

    def set_text(self, labels):
        self._labels = [str(L) for L in labels] if labels else []

    def get_text(self):
        return list(self._labels)

    def set_visible(self, b):
        self._visible = bool(b)

    def get_visible(self):
        return self._visible

    def set_fontsize(self, s):    self._fontsize = float(s)
    def get_fontsize(self):       return self._fontsize
    def set_color(self, c):       self._color = c
    def get_color(self):          return self._color
    def set_rotation(self, r):    self._rotation = float(r)
    def get_rotation(self):       return self._rotation


class Ticks:
    """Tick-glyph container — stores size + visibility + direction."""

    def __init__(self, ticksize):
        self._ticksize = float(ticksize)
        self._visible = True
        self._tickdir = 'in'
        self._color = 'black'

    def set_ticksize(self, s):    self._ticksize = float(s)
    def get_ticksize(self):       return self._ticksize
    def set_visible(self, b):     self._visible = bool(b)
    def get_visible(self):        return self._visible
    def set_tickdir(self, d):     self._tickdir = d
    def get_tickdir(self):        return self._tickdir
    def set_color(self, c):       self._color = c
    def get_color(self):          return self._color


class AxisLine:
    """The axis-spine line."""

    def __init__(self):
        self._visible = True
        self._color = 'black'
        self._linewidth = 1.0
        self._linestyle = '-'

    def set_visible(self, b):     self._visible = bool(b)
    def get_visible(self):        return self._visible
    def set_color(self, c):       self._color = c
    def get_color(self):          return self._color
    def set_linewidth(self, w):   self._linewidth = float(w)
    def get_linewidth(self):      return self._linewidth
    def set_linestyle(self, s):   self._linestyle = s
    def get_linestyle(self):      return self._linestyle


