class AttributeCopier:
    """Mixin that copies a subset of attributes from a source artist onto
    this one. Used by ticks/labels to inherit fonts/sizes from their
    parent Axis."""

    def __init__(self):
        self._copy_targets = ()

    def set_attribute_copier(self, attribs):
        """Configure which attribute names to copy."""
        self._copy_targets = tuple(attribs)

    def copy_attributes_from(self, src):
        for attr in self._copy_targets:
            if hasattr(src, attr):
                setattr(self, attr, getattr(src, attr))


class LabelBase:
    """Base class for axis label artists. Holds the label text, its
    rotation, and a flag for whether to use mathtext."""

    def __init__(self, text='', rotation=0, math_mode=False):
        self._text = text
        self._rotation = rotation
        self._math_mode = math_mode

    def get_text(self):                return self._text
    def set_text(self, s):             self._text = s
    def get_rotation(self):            return self._rotation
    def set_rotation(self, r):         self._rotation = r


class GridlinesCollection:
    """Container of gridline artists. Implements add/remove/iter so
    callers can manage the gridlines uniformly."""

    def __init__(self):
        self._lines = []

    def __iter__(self):    return iter(self._lines)
    def __len__(self):     return len(self._lines)
    def add(self, line):   self._lines.append(line); return line
    def remove(self, line):
        try: self._lines.remove(line)
        except ValueError: pass
    def set_visible(self, b):
        for L in self._lines:
            if hasattr(L, 'set_visible'): L.set_visible(b)
